/* * All the article header values worth retaining. * (strictly from headers in input.) * * All members of struct headers must point at malloced memory so that * freeheaders() can free it without having to keep track of what's * malloced and what's static. * * Furthermore, each member of headers must point at its own private copy * of its value string, for the above reason, and no code outside hdr*.c * may copy any member nor a modified copy of any member, though it may * copy the string pointed to by a (possibly modified) member. * * Perhaps C++ will allow this to be enforced by a strings class. * See section 6.9 of The C++ Programming Language for a candidate. */struct headers {	char *h_subj;	/* subject: only needed for controls, -> h_ctlcmd */	char *h_ngs;	/* newsgroups: used in filing, sys matching & all.all.ctl matching */	char *h_distr;	/* distribution for transmit */	char *h_ctlcmd;	/* control command (NCMP) */	char *h_etctlcmd;	/* also-control command (NCMP) */	char *h_approved;	/* needed for acceptance in moderated groups */	char *h_msgid;	/* needed for history & rejection */	char *h_artid;	/* needed for history & rejection (obs.) */	char *h_expiry;	/* needed for history */	char *h_path;	/* needed for transmit - must munge */	char *h_sender;	/* needed for transmit in case of moderation */};/* common */extern void hdrdebug(), hdrinit(), freeheaders();extern boolean oldctl();/* munge */extern void emitxref(), hdrdump(), hdrdigest();/* parse */extern void hdrparse(), hdrdeflt();extern boolean ishdr(), contin();